<script setup lang="ts">
import { computed, nextTick, onMounted, ref, watch } from 'vue'
import UButton from '@nuxt/ui/components/Button.vue'
import GuidancePanel from './GuidancePanel.vue'
import ConversationTaskStatus from './ConversationTaskStatus.vue'
import ConversationGroupPanel from './ConversationGroupPanel.vue'
import ConversationBusinessPanel from './ConversationBusinessPanel.vue'
import { createConversationController } from './conversation-state'
import { dataPolicyLabel, intentStatusLabel, proposalStatusLabel, resourceIdentityLabel, conversationIssueLabel, catalogueSourceLabel } from './conversation-view'
import { errorText, formatTime, jobLabel, scopeLabel, sourceLabel, useWorkspace } from './workspace'

const workspace = useWorkspace()
const controller = (workspace.drafts.get('conversation-controller') as ReturnType<typeof createConversationController> | undefined) ?? createConversationController(workspace, errorText)
workspace.drafts.set('conversation-controller', controller)
const editor = controller.editor, intent = workspace.currentIntent, selectedJobID = ref(''), contextOpen = ref(true), messagesElement = ref<HTMLElement | null>(null)
const businessPending = ref(false), businessBusy = ref(false), groupPending = ref(false), groupBusy = ref(false)
const conversationJobs = computed(() => workspace.jobs.value.filter(job => job.conversation_id === workspace.conversationID.value))
const selectedJob = computed(() => conversationJobs.value.find(job => job.id === selectedJobID.value) ?? controller.currentJob.value ?? conversationJobs.value[0] ?? null)
const hasUnknownPlanningSubmission = computed(() => !!editor.value.turn.pendingBody || !!editor.value.choice.pendingBody || !!editor.value.acceptance.pendingBody)
const hasUnknownSubmission = computed(() => hasUnknownPlanningSubmission.value || businessPending.value || groupPending.value)
async function selectConversation(event: Event) {
  const id = (event.target as HTMLSelectElement).value
  if (!id) return
  try { await workspace.selectConversation(id); selectedJobID.value = '' }
  catch (cause) { editor.value.error = errorText(cause) }
}
async function send() { if (businessBusy.value || businessPending.value || groupBusy.value || groupPending.value) return; await controller.send(); await scrollMessages() }
async function scrollMessages() { await nextTick(); if (messagesElement.value) messagesElement.value.scrollTop = messagesElement.value.scrollHeight }
function keyboard(event: KeyboardEvent) { if (event.key === 'Enter' && !event.shiftKey && !event.isComposing) { event.preventDefault(); void send() } }
function initializeOptions() { if (!editor.value.optionsInitialized && intent.value) controller.resetOptions() }
watch(() => workspace.conversationID.value, () => { selectedJobID.value = ''; initializeOptions(); void scrollMessages() })
watch(() => intent.value?.revision, () => { initializeOptions(); editor.value.candidateIDs = [] })
watch(() => workspace.messages.value.length, () => { void scrollMessages() })
watch(() => editor.value.acceptance.result?.job, job => { if (job && job.conversation_id === workspace.conversationID.value) { selectedJobID.value = job.id; contextOpen.value = true } })
watch(() => editor.value.turn.result?.job, job => { if (job && job.conversation_id === workspace.conversationID.value) { selectedJobID.value = job.id; contextOpen.value = true } })
onMounted(async () => { if (workspace.conversationID.value) { try { await Promise.all([workspace.loadMessages(), workspace.loadIntent()]); initializeOptions() } catch (cause) { editor.value.error = errorText(cause) } } })
</script>

<template>
  <div class="conversation-workspace">
    <header class="conversation-page-title"><div><span class="conversation-kicker">审计对话</span><h1>{{ workspace.currentConversation.value?.title || '从这次审计目标开始' }}</h1><p>先明确对象，再核对资料与执行计划。云端只读，整改由你审阅并手动应用。</p></div><UButton color="neutral" variant="outline" size="sm" :aria-expanded="contextOpen" aria-controls="conversation-context" @click="contextOpen = !contextOpen">对象与结果</UButton></header>
    <div class="conversation-session-bar"><label for="planning-conversation">当前会话</label><select id="planning-conversation" :value="workspace.conversationID.value" @change="selectConversation"><option value="">新的目标</option><option v-for="conversation in workspace.conversations.value" :key="conversation.id" :value="conversation.id">{{ conversation.title }}{{ conversation.archived ? '（已归档）' : '' }}</option></select><UButton color="neutral" variant="outline" :disabled="editor.busy" @click="controller.createConversation">{{ controller.creation.state === 'unsaved' ? '核对原会话创建' : '新建对话' }}</UButton><button v-if="workspace.conversationID.value" type="button" class="text-action" :disabled="editor.busy" @click="controller.readCurrent">读取保存记录</button><button v-if="workspace.listHasMore.value.conversations" type="button" class="text-action" :disabled="workspace.listsLoading.value" @click="workspace.loadMore('conversations')">读取更早会话</button></div>
    <p v-if="controller.creation.state === 'unsaved'" class="notice notice-warning" role="status">新会话创建结果尚未确认。再次操作沿用原提交标识，不会后台重发。</p>
    <div :class="['conversation-workspace-layout', { 'context-is-closed': !contextOpen }]">
      <section class="conversation-primary" aria-label="连续审计对话">
        <div ref="messagesElement" class="planning-messages" role="log" aria-label="持久会话消息" aria-live="polite" aria-relevant="additions">
          <div v-if="!workspace.messages.value.length" class="conversation-welcome"><svg viewBox="0 0 40 40" aria-hidden="true"><path d="M8 10h24v16H20l-8 6v-6H8Z" fill="none" stroke="currentColor" stroke-width="1.7"/><path d="M14 16h12M14 21h8" stroke="currentColor" stroke-width="1.7"/></svg><h2>这次想检查哪些资源？</h2><p>可以给名称、ID、地域、资源类型或有来源的业务群。没有快照也能先保存目标、澄清对象和核对下一步。</p><p class="field-hint">消息与目标保存在本机服务。当前没有证据时，不生成安全结论。</p></div>
          <article v-for="message in workspace.messages.value" :key="message.id" :class="['planning-message', { 'is-user': message.role === 'user' }]"><div class="planning-message-meta"><strong>{{ message.role === 'user' ? '你' : message.origin === 'model' ? '审计助手' : '应用记录' }}</strong><time>{{ formatTime(message.created_at) }}</time></div><p>{{ message.public_text }}</p><button v-if="message.job_id" type="button" class="text-action" @click="selectedJobID = message.job_id; contextOpen = true">查看这条消息关联的任务</button></article>
          <button v-if="workspace.messagesHasMore.value" type="button" class="text-action" @click="workspace.loadMessages(true).catch(cause => editor.error = errorText(cause))">继续读取会话记录</button>
          <section v-if="intent?.clarification" class="conversation-clarification"><h2>还需要明确</h2><p>{{ intent.clarification }}</p><p class="field-hint">补充说明会更新同一会话目标，原执行任务和报告保留原版本。</p></section>
          <section v-if="intent?.candidates.length" class="conversation-candidate-card" aria-labelledby="candidate-heading"><header><h2 id="candidate-heading">选择本次对象</h2><span class="tag tag-neutral">{{ intent.candidates.length }} 个已返回候选</span></header><p>按规范身份核对。名称、标签或相近地址不自动代表同一个对象。</p><fieldset :disabled="editor.busy || hasUnknownSubmission"><legend class="sr-only">资源候选</legend><label v-for="candidate in intent.candidates" :key="candidate.id" class="conversation-candidate"><input v-model="editor.candidateIDs" type="checkbox" :value="candidate.id" /><span><strong>{{ candidate.name || candidate.local_asset_id || candidate.resource_id || '未命名对象' }}</strong><span>{{ candidate.region || '地域未知' }} / {{ candidate.resource_type || '类型未知' }} / {{ resourceIdentityLabel(candidate) }}</span><small>{{ catalogueSourceLabel(candidate.source) }}；{{ formatTime(candidate.observed_at) }}</small></span></label></fieldset><p v-if="!intent.catalogue.complete" class="notice notice-warning">目录尚未穷尽。这里只列已取得的候选，未匹配不能证明资源不存在。</p><UButton :disabled="editor.busy || businessBusy || businessPending || groupBusy || groupPending || !editor.candidateIDs.length && !editor.choice.pendingBody" @click="controller.choose">{{ editor.busy ? '保存选择中…' : editor.choice.pendingBody ? '核对原选择并重试' : '确认所选对象' }}</UButton></section>
          <section v-if="intent?.proposal" class="conversation-proposal" aria-labelledby="proposal-heading"><header><h2 id="proposal-heading">本次执行计划</h2><span class="tag tag-neutral">{{ proposalStatusLabel(intent.proposal.status) }}</span></header><p>{{ intent.proposal.summary }}</p><dl><dt>审计范围</dt><dd>{{ scopeLabel(intent.boundary, intent.direction) }}；{{ intent.selection.length ? `${intent.selection.length} 个已明确对象` : '对象将在已接受的有限准备范围内解析' }}</dd><dt>资料策略</dt><dd>{{ dataPolicyLabel(intent.data_policy.mode) }}</dd><dt>执行模式</dt><dd>{{ intent.mode === 'rules_only' ? '仅运行确定性规则' : '规则后由受限模型补充' }}</dd><dt>云读取</dt><dd>{{ intent.proposal.effects.allow_cloud_reads ? '允许计划范围内的只读准备' : '本计划不允许新增云读取' }}</dd><dt>模型效果</dt><dd>{{ intent.proposal.effects.allow_model_requests ? '允许本次有界模型补充' : '本计划不使用模型请求' }}</dd></dl><ul v-if="intent.proposal.gaps.length || intent.proposal.warnings.length" class="conversation-plan-notes"><li v-for="item in [...intent.proposal.gaps, ...intent.proposal.warnings]" :key="item">{{ conversationIssueLabel(item) }}</li></ul><p v-if="controller.optionsChanged.value" class="notice notice-warning">下面的模式或资料策略改动尚未保存。先发送说明或核对选项，才能接受新计划。</p><p v-if="controller.currentJob.value" class="field-hint">此会话已有未结束任务。可以查看进度或明确取消，服务端不会并行启动第二个任务。</p><UButton :disabled="editor.busy || businessBusy || businessPending || groupBusy || groupPending || !editor.acceptance.pendingBody && !controller.canAccept.value" @click="controller.accept">{{ editor.acceptance.pendingBody ? '以原计划标识核对并重试' : intent.proposal.requires_discovery ? '接受有限资料准备计划' : '接受计划并开始' }}</UButton></section>
        </div>
        <div class="planning-composer"><GuidancePanel surface="conversation" :conversation-id="workspace.conversationID.value" :disabled="hasUnknownSubmission || editor.busy" /><form @submit.prevent="send"><label for="planning-message" class="sr-only">目标、补充说明或追问</label><textarea id="planning-message" v-model="editor.text" maxlength="4000" rows="3" :disabled="editor.busy || businessBusy || businessPending || groupBusy || groupPending || !!editor.turn.pendingBody" placeholder="例如：审计杭州 web-prod 的互联网入向；管理来源未知，先查基线" @keydown="keyboard" /><div class="planning-compose-actions"><span>请勿输入凭据；Enter 发送，Shift + Enter 换行</span><UButton type="submit" :disabled="editor.busy || businessBusy || businessPending || groupBusy || groupPending || !editor.text.trim() && !editor.turn.pendingBody">{{ editor.busy ? '保存中…' : editor.turn.pendingBody ? '以原内容核对并重试' : '发送' }}</UButton></div></form><details class="planning-options"><summary>本次模式与资料策略</summary><fieldset :disabled="editor.busy || hasUnknownSubmission"><label>执行模式<select v-model="editor.mode" @change="editor.optionsInitialized = true; editor.modeEdited = true"><option value="rules_only">只运行规则</option><option value="rules_and_agent">规则与模型补充</option></select></label><label>资料策略<select v-model="editor.dataPolicy" @change="editor.optionsInitialized = true; editor.dataPolicyEdited = true"><option value="prefer_fresh">合格复用，必要时更新</option><option value="force_refresh">重新采集当前范围</option><option value="pinned_snapshot">使用所选固定历史资料</option></select></label><p>{{ workspace.modelState.value.label }}。已配置或可用不等于本次已授权；最终效果以接受的服务端计划为准。</p><p v-if="editor.dataPolicy === 'pinned_snapshot'">{{ workspace.currentSnapshot.value ? `当前所选：${sourceLabel(workspace.currentSnapshot.value.source_kind)} / ${formatTime(workspace.currentSnapshot.value.input.collected_at)}` : '尚未选择固定资料，请在数据与任务中选择。' }}</p><button v-if="controller.optionsChanged.value" type="button" class="text-action" @click="controller.send('按已明确的对象核对本次执行模式与资料策略')">核对这些选项</button><button v-if="controller.optionsChanged.value" type="button" class="text-action" @click="controller.resetOptions">恢复已保存的选项</button></fieldset></details><p v-if="editor.error" class="error-text" role="alert">{{ editor.error }}</p><div v-if="hasUnknownPlanningSubmission" class="conversation-unknown-submission"><p>上次操作结果尚需核对，原内容、对象与提交标识已保留。</p><button type="button" class="text-action" @click="controller.readCurrent">读取服务器保存记录</button><button v-if="!editor.acceptance.pendingBody" type="button" class="text-action" @click="controller.discardUnknown">核对记录后重新编辑</button></div></div>
      </section>
      <aside v-show="contextOpen" id="conversation-context" class="planning-context" aria-label="当前会话对象、资料与结果">
        <section v-if="intent" class="planning-context-section"><header><h2>当前目标</h2><span class="tag tag-neutral">{{ intentStatusLabel(intent.status) }}</span></header><p>{{ scopeLabel(intent.boundary, intent.direction) }}</p><p v-if="!intent.selection.length" class="field-hint">对象尚未全部明确，选择候选或补充说明后再核对。</p><details v-else :open="intent.selection.length < 4"><summary>{{ intent.selection.length }} 个明确对象</summary><div v-for="item in intent.selection" :key="item.id" class="planning-object"><strong>{{ item.name || item.local_asset_id || item.resource_id || '未命名对象' }}</strong><span>{{ item.region || '地域未知' }} / {{ item.resource_type || '类型未知' }} / {{ resourceIdentityLabel(item) }}</span><small>{{ catalogueSourceLabel(item.source) }}；{{ formatTime(item.observed_at) }}</small></div></details><h3>目录来源与完整性</h3><p>{{ catalogueSourceLabel(intent.catalogue.source) }}<br />{{ formatTime(intent.catalogue.observed_at) }}<br />{{ intent.catalogue.complete ? '本次目录范围声明完整' : '目录尚未知或未穷尽' }}</p><ul v-if="intent.catalogue.limitations.length" class="conversation-plan-notes"><li v-for="item in intent.catalogue.limitations" :key="item">{{ conversationIssueLabel(item) }}</li></ul><p class="field-hint">目录新鲜不代表策略或引用完整。审计输入将在执行时单独封存。</p></section>
        <section v-else class="planning-context-section context-empty"><svg viewBox="0 0 40 40" aria-hidden="true"><rect x="10" y="5" width="22" height="30" rx="4" fill="none" stroke="currentColor" stroke-width="1.5"/><path d="M15 13h12M15 20h12M15 27h7" stroke="currentColor" stroke-width="1.5"/></svg><h2>从目标建立上下文</h2><p>明确后的对象、资料来源和执行效果会显示在这里。没有运行时，不显示风险为零。</p></section>
        <ConversationTaskStatus v-if="selectedJob" :key="selectedJob.id" :job-id="selectedJob.id" :conversation-id="workspace.conversationID.value" />
        <ConversationGroupPanel :conversation-id="workspace.conversationID.value" :disabled="hasUnknownPlanningSubmission || editor.busy || businessBusy || businessPending" @state="value => { groupPending = value.pending; groupBusy = value.busy }" />
        <ConversationBusinessPanel :conversation-id="workspace.conversationID.value" :disabled="hasUnknownPlanningSubmission || editor.busy || groupBusy || groupPending" @state="value => { businessPending = value.pending; businessBusy = value.busy }" />
        <section v-if="conversationJobs.length" class="planning-context-section"><h2>本会话任务与历史</h2><button v-for="job in conversationJobs" :key="job.id" type="button" :class="['planning-history-job', { active: selectedJob?.id === job.id }]" @click="selectedJobID = job.id"><span>{{ jobLabel(job.status) }}</span><time>{{ formatTime(job.created_at) }}</time></button><RouterLink to="/reports">打开固定报告与审阅</RouterLink></section>
        <section class="planning-context-section planning-help"><h2>需要补资料时</h2><p>角色、允许访问、必要访问与例外分别确认；不知道白名单仍可检查独立基线。</p><RouterLink to="/overview">资料、连接与离线导入</RouterLink><RouterLink to="/inventory">打开业务资料视图并核对对象</RouterLink><p class="field-hint">业务视图另按所选资料编辑，不能把当前所选快照自动当作此目标的确认。</p></section>
      </aside>
    </div>
  </div>
</template>
